const solarBatteryBank = {
  slug: 'solar-battery-bank-calculator',
  category: CATEGORY,
  kicker: 'Battery storage sizing',
  h1: 'Solar Battery Bank Calculator',
  title: 'Solar Battery Bank Calculator — Ah & kWh Storage | Ampstowatt',
  metaDesc: 'Size a solar battery bank in amp-hours and kWh from daily energy use, days of autonomy, voltage, and depth of discharge. See how many 100Ah batteries you need.',
  keywords: ['solar battery bank calculator', 'how many batteries for solar calculator', 'solar battery size calculator', 'off grid battery bank calculator', 'battery storage sizing'],
  formulaPill: 'Ah = (Daily Wh × Days) ÷ (Voltage × DoD)',
  lead: 'This <strong>solar battery bank calculator</strong> sizes your storage in amp-hours and kilowatt-hours from daily energy use, days of autonomy, bank voltage, and depth of discharge. It also tells you how many 100Ah batteries you need to survive cloudy days without over-draining the bank.',
  reviewed: REVIEWED,
  featureList: ['Battery bank size in Ah and kWh', 'Days-of-autonomy and depth-of-discharge aware', 'Supports 12V, 24V, and 48V banks', 'Counts 100Ah batteries required'],
  methodology: 'The required amp-hours equal daily watt-hours multiplied by days of autonomy, divided by the product of bank voltage and usable depth of discharge. Usable energy is daily Wh × days; total installed energy is Ah × voltage. Depth-of-discharge defaults follow chemistry norms — 80% for LiFePO4 lithium, 50% for lead-acid.',
  calc: {
    id: 'solar-battery-bank',
    title: 'Solar Battery Bank Calculator',
    subtitle: 'Storage size in Ah and kWh for your system.',
    primaryLabel: 'Battery Bank Size',
    primaryUnit: 'Ah',
    formulaText: 'Ah = (Daily Wh × Days) ÷ (Voltage × DoD)',
    note: 'Amp-hours at the selected bank voltage.',
    secondary: [
      { label: 'Usable Energy', unit: 'kWh' },
      { label: 'Total Installed Energy', unit: 'kWh' },
      { label: '100Ah Batteries Needed', unit: 'batteries' },
    ],
    inputs: [
      { id: 'dailyWh', label: 'Daily Energy Use', unit: 'Wh', type: 'number', value: 3000, min: 0 },
      { id: 'days', label: 'Days of Autonomy', unit: 'days', type: 'number', value: 2, min: 0.1, step: 0.5 },
      { id: 'voltage', label: 'Bank Voltage', unit: 'V', type: 'select', value: '48', options: [{ v: '12', t: '12 V' }, { v: '24', t: '24 V' }, { v: '48', t: '48 V' }] },
      { id: 'dod', label: 'Depth of Discharge', unit: '%', type: 'number', value: 80, min: 1, max: 100 },
    ],
    compute: function compute(v) {
      var volts = parseFloat(v.voltage);
      var ah = (v.dailyWh * v.days) / (volts * (v.dod / 100));
      var usableKWh = (v.dailyWh * v.days) / 1000;
      var totalKWh = (ah * volts) / 1000;
      var batteries = Math.ceil(ah / 100);
      return {
        primary: { label: 'Battery Bank Size', value: ah, unit: 'Ah', precision: 1 },
        secondary: [
          { label: 'Usable Energy', value: usableKWh, unit: 'kWh', precision: 2 },
          { label: 'Total Installed Energy', value: totalKWh, unit: 'kWh', precision: 2 },
          { label: '100Ah Batteries Needed', value: batteries, unit: 'batteries', precision: 0 },
        ],
        formula: 'Ah = (' + v.dailyWh + ' × ' + v.days + ') ÷ (' + volts + ' × ' + v.dod + '%)',
        note: Math.round(ah) + ' Ah at ' + volts + ' V ≈ ' + batteries + ' × 100Ah.',
      };
    },
    tests: [
      { name: '3000Wh 2d 48V 80%', in: { dailyWh: 3000, days: 2, voltage: '48', dod: 80 }, expect: 156.25, tol: 0.01 },
      { name: '2400Wh 1d 12V 50%', in: { dailyWh: 2400, days: 1, voltage: '12', dod: 50 }, expect: 400, tol: 0.01 },
    ],
  },
  content: [
    { type: 'section', id: 'quick-answer', icon: '⚡', heading: 'How Big a Solar Battery Bank Do You Need? Quick Answer', html: `<p class="content-p"><strong>Multiply daily watt-hours by days of autonomy, then divide by bank voltage and depth of discharge.</strong> A system using 3,000 Wh per day, needing 2 days of backup, on a 48V lithium bank at 80% depth of discharge, requires (3,000 × 2) ÷ (48 × 0.80) = 6,000 ÷ 38.4 = <strong>156 Ah</strong> — about 6 kWh of usable storage, or two 100Ah batteries. The calculator above returns amp-hours, usable and total kWh, and the number of 100Ah batteries.</p><p class="content-p">Two numbers drive battery bank size: <strong>how much energy you use per day</strong> and <strong>how many days you must run without sun</strong>. Depth of discharge then decides how much of the bank is actually usable — you cannot drain any battery to zero without destroying its lifespan. Building depth of discharge into the math is why a "6 kWh" load needs a bank rated well above 6 kWh of nameplate capacity.</p>` },
    { type: 'section', id: 'formula', icon: 'f(x)', heading: 'The Battery Bank Sizing Formula', html: `<p class="content-p">This calculator uses:</p><div class="tool-guide-formula">Amp-Hours = (Daily Wh × Days of Autonomy) ÷ (Bank Voltage × Depth of Discharge)</div><p class="content-p">Each term controls the result:</p><ul><li><strong>Daily Wh</strong> — total daily energy the bank must supply. Sum every load's watt-hours, or take daily kWh × 1,000.</li><li><strong>Days of Autonomy</strong> — how many consecutive cloudy days the bank carries the load with no solar input. Weekend users pick 1; full-time off-grid homes pick 2–3, more in cloudy climates.</li><li><strong>Bank Voltage</strong> — 12V for small systems, 24V for mid-size, 48V for whole-home. Higher voltage means fewer amp-hours for the same energy and thinner cable.</li><li><strong>Depth of Discharge (DoD)</strong> — the usable fraction. 80–100% for LiFePO4 lithium, 50% for lead-acid to protect cycle life.</li></ul><p class="content-p">Note how voltage and amp-hours trade off: the same 6 kWh usable bank is 156Ah at 48V but 625Ah at 12V. Energy (kWh) is what matters; amp-hours only make sense alongside a voltage. To turn amp-hours back into energy, use our <a href="/amp-hours-to-watt-hours/">amp-hours to watt-hours</a> converter, and to check how long a given bank runs a load, the <a href="/battery-runtime-calculator/">battery runtime calculator</a>.</p>`, table: { caption: 'Recommended depth of discharge and days of autonomy by chemistry and use', columns: ['Battery Type', 'Recommended DoD', 'Typical Autonomy', 'Best For'], rows: [['LiFePO4 (Lithium)', '80–100%', '1–3 days', 'Off-grid homes, RV, marine'], ['AGM Lead-Acid', '50%', '2–3 days', 'Backup, occasional use'], ['Flooded Lead-Acid', '50%', '3–5 days', 'Budget off-grid banks'], ['Gel Lead-Acid', '50%', '2–3 days', 'Deep-cycle backup']] } },
    { type: 'section', id: 'examples', icon: '#', heading: 'Worked Examples: Sizing Solar Storage', html: `<p class="content-p"><strong>Example 1 — Cabin, 3,000 Wh/day, 2 days, 48V lithium, 80% DoD:</strong> Ah = (3,000 × 2) ÷ (48 × 0.80) = 6,000 ÷ 38.4 = <strong>156.25 Ah</strong>. Usable energy is 6 kWh; total installed energy is 156.25 × 48 = 7.5 kWh. That is two 100Ah 48V modules, or a single 200Ah unit for headroom.</p><p class="content-p"><strong>Example 2 — Same load on lead-acid at 50% DoD:</strong> Ah = 6,000 ÷ (48 × 0.50) = 6,000 ÷ 24 = <strong>250 Ah</strong>. Halving the usable depth nearly doubles the required amp-hours — a clear illustration of why lithium banks are smaller and lighter.</p><p class="content-p"><strong>Example 3 — Small 12V system, 2,400 Wh/day, 1 day, 50% DoD:</strong> Ah = (2,400 × 1) ÷ (12 × 0.50) = 2,400 ÷ 6 = <strong>400 Ah</strong> — four 100Ah 12V batteries in parallel. On 48V lithium at 80% the same load needs only 62.5 Ah.</p><p class="content-p"><strong>Example 4 — Off-grid home, 10,000 Wh/day, 3 days, 48V lithium, 90% DoD:</strong> Ah = (10,000 × 3) ÷ (48 × 0.90) = 30,000 ÷ 43.2 = <strong>694 Ah</strong>, about 33.3 kWh installed — a large residential lithium bank sized for three sunless days.</p>` },
    { type: 'section', id: 'autonomy', icon: '☀', heading: 'Choosing Days of Autonomy and Depth of Discharge', html: `<p class="content-p">Days of autonomy is the most consequential choice you make, because it multiplies bank size directly. It answers: if the sun disappears, how long must the batteries carry the house? The right number depends on climate and risk tolerance.</p><p class="content-p">In sunny, reliable climates like the Southwest, 1–2 days is common because clear weather returns quickly and a generator covers rare gaps. In cloudy or stormy regions, 3–5 days is safer. Grid-backup systems can use as little as 0.5–1 day because the grid, not the battery, is the primary source. Every extra day adds proportional cost, so many designers cap autonomy at 2–3 days and add a generator or extra solar rather than an enormous battery.</p><p class="content-p">Depth of discharge is the other lever. Draining a LiFePO4 battery to 80–90% each cycle is fine and still yields thousands of cycles. Draining lead-acid past 50% can slash its life from 500 cycles to under 200. Sizing to a conservative DoD protects the investment. Pair this with the <a href="/battery-bank-size-calculator/">battery bank size calculator</a> for autonomy-focused sizing and the <a href="/off-grid-solar-calculator/">off-grid solar calculator</a> to match panels to the bank.</p>`, table: { caption: 'How bank size scales with days of autonomy (3,000 Wh/day, 48V, 80% DoD)', columns: ['Days of Autonomy', 'Required Ah', 'Usable kWh', 'Installed kWh'], rows: [['1 day', '78 Ah', '3.0', '3.75'], ['2 days', '156 Ah', '6.0', '7.50'], ['3 days', '234 Ah', '9.0', '11.25'], ['4 days', '313 Ah', '12.0', '15.00'], ['5 days', '391 Ah', '15.0', '18.75']] } },
    { type: 'section', id: 'how-to-use', icon: '✓', heading: 'How to Use the Solar Battery Bank Calculator', html: `<ol><li><strong>Enter daily energy use in watt-hours.</strong> Add every appliance's watt-hours, or convert daily kWh × 1,000.</li><li><strong>Set days of autonomy.</strong> 1 for grid-backup or sunny sites, 2–3 for off-grid, 3–5 for cloudy climates.</li><li><strong>Choose bank voltage.</strong> 12V for small setups, 24V for mid-size, 48V for whole-home efficiency.</li><li><strong>Set depth of discharge.</strong> 80–90% for lithium, 50% for lead-acid.</li><li><strong>Read the results.</strong> Primary is amp-hours; secondary gives usable kWh, total installed kWh, and 100Ah battery count.</li></ol>` },
    { type: 'section', id: 'series-parallel', icon: '⇄', heading: 'Series vs Parallel: Building the Bank', html: `<p class="content-p">The amp-hours and voltage this calculator returns must be assembled from individual batteries, and how you wire them determines whether you gain voltage or capacity. Getting this right is essential to hitting the target bank size safely.</p><p class="content-p"><strong>Series wiring</strong> (positive to negative) adds voltage while amp-hours stay constant. Four 12V 100Ah batteries in series make a 48V 100Ah bank — 4,800 Wh. <strong>Parallel wiring</strong> (positive to positive) adds amp-hours while voltage stays constant. Four 12V 100Ah batteries in parallel make a 12V 400Ah bank — also 4,800 Wh. <strong>Series-parallel</strong> combines both: eight 12V 100Ah batteries as 48V 200Ah delivers 9,600 Wh. The stored energy in watt-hours is identical for a given set of batteries; only the voltage-versus-current split changes.</p><p class="content-p">This is why the calculator lets you pick bank voltage: the same usable kWh becomes far fewer amp-hours at 48V than at 12V, allowing thinner cable and smaller breakers. A practical caution — avoid wiring more than three or four battery strings in parallel, because current sharing becomes uneven and a weak string can be overworked. Manufacturers of drop-in lithium batteries publish maximum parallel counts. For large banks, prefer higher voltage over many parallel strings. To convert any bank's amp-hours back into energy, use the <a href="/amp-hours-to-watt-hours/">amp-hours to watt-hours</a> converter, and to see how long the finished bank runs a specific load, the <a href="/battery-runtime-calculator/">battery runtime calculator</a>.</p>` },
    { type: 'section', id: 'temperature', icon: '°', heading: 'Temperature, Charge Rate, and Cycle Life', html: `<p class="content-p">A battery bank's real-world capacity and lifespan depend on factors the nameplate does not show, and understanding them helps you set depth of discharge and autonomy honestly. Temperature is the biggest. Batteries are rated near 25°C (77°F); lead-acid loses 20–35% of usable capacity near freezing, and lithium loses some capacity in the cold and must not be charged below 0°C without an internal heater. In hot climates, sustained heat accelerates aging and self-discharge. If your bank lives in an uninsulated shed or a vehicle, plan for reduced winter capacity or add insulation and heating.</p><p class="content-p">Charge rate matters too. A battery can only absorb charge so fast, expressed as a C-rate: 0.5C means a 100Ah battery accepts up to 50A. If your solar array can deliver more current than the bank can absorb, the charge controller limits it and you lose midday harvest. Sizing the array's charging current between roughly 0.1C and 0.5C of the bank keeps charging efficient without stressing the cells.</p><p class="content-p">Finally, depth of discharge trades directly against cycle life. A LiFePO4 bank cycled to 80% might last 3,000–6,000 cycles; the same bank cycled shallower lasts even longer. Lead-acid cycled to 50% may reach 500 cycles but collapses to under 200 if routinely drained deeper. Sizing generously and discharging shallowly is the cheapest way to extend bank life. Pair this with the <a href="/off-grid-solar-calculator/">off-grid solar calculator</a> to match the array to the bank you size here.</p>` },
    { type: 'section', id: 'mistakes', icon: '!', heading: 'Common Battery Bank Sizing Mistakes', html: `<ul><li><strong>Sizing to usable energy but buying nameplate.</strong> A 6 kWh daily need at 80% DoD requires 7.5 kWh installed, not 6 kWh.</li><li><strong>Draining lead-acid past 50%.</strong> It technically works but destroys cycle life; always size lead-acid at 50% DoD.</li><li><strong>Forgetting round-trip and inverter losses.</strong> Add 10–20% headroom, or lower DoD, so real runtime matches the plan.</li><li><strong>Mixing chemistries or ages.</strong> A weak or mismatched battery drags down the entire parallel bank.</li><li><strong>Choosing too many autonomy days.</strong> Every extra day adds cost; a generator is often cheaper than a fifth day of battery.</li></ul>` },
    { type: 'section', id: 'applications', icon: '⌂', heading: 'Bank Sizing for RV, Cabin, and Whole-Home', html: `<p class="content-p"><strong>RV and van.</strong> Typical banks run 100–400Ah at 12V (1.2–5 kWh). One or two days of autonomy is plenty because you move to sun and can charge from the alternator or shore power.</p><p class="content-p"><strong>Off-grid cabin.</strong> Weekend cabins often use 200–400Ah at 12V or 24V; full-time cabins move to 48V and 400–800Ah (10–20 kWh) with 2–3 days of autonomy.</p><p class="content-p"><strong>Whole-home off-grid.</strong> These systems almost always use 48V for efficiency and safety, with banks of 20–40 kWh and 2–3 days of autonomy, backed by a generator for the darkest stretches.</p><p class="content-p">Whatever the scale, size the bank from real daily consumption and a realistic autonomy target, then confirm the solar array can recharge it with the <a href="/solar-panel-wattage-calculator/">solar panel wattage calculator</a> and protect it with a correctly sized <a href="/solar-charge-controller-size-calculator/">charge controller</a>. One more planning tip: buy the bank you will need in two or three years, not just today. Batteries are easiest to match when purchased together as a single set, because paralleling a brand-new module with a bank that has already aged and lost capacity drags the whole bank down to the weaker cells. Sizing with a little growth headroom now avoids an awkward and inefficient mixed-age expansion later.</p>` },
  ],
  faq: [
    { q: 'How many batteries do I need for solar?', a: 'Multiply daily watt-hours by days of autonomy, divide by voltage and depth of discharge to get amp-hours, then divide by your battery amp-hours. A 3,000 Wh/day load with 2 days autonomy on a 48V lithium bank at 80% DoD needs 156Ah — about two 100Ah batteries.' },
    { q: 'How do I calculate solar battery bank size in kWh?', a: 'Usable kWh equals daily Wh × days of autonomy ÷ 1,000. To get the installed (nameplate) kWh, divide usable by your depth of discharge. A 6 kWh usable need at 80% DoD requires 7.5 kWh of installed battery capacity.' },
    { q: 'What depth of discharge should I use for a solar battery?', a: 'Use 80–90% for LiFePO4 lithium and 50% for AGM, gel, or flooded lead-acid. Lithium tolerates deep cycling with minimal wear, while draining lead-acid below 50% sharply shortens its cycle life.' },
    { q: 'How many days of autonomy do I need?', a: 'Sunny climates and grid-backup systems use 1–2 days; off-grid homes typically use 2–3; cloudy or storm-prone regions use 3–5. Each extra day multiplies battery cost, so many designers cap autonomy and add a generator instead.' },
    { q: 'Should I use a 12V, 24V, or 48V battery bank?', a: 'Use 12V for small RV and marine systems, 24V for mid-size cabins, and 48V for whole-home off-grid. Higher voltage means fewer amp-hours for the same energy, thinner cables, lower current, and better inverter efficiency.' },
    { q: 'Why is my installed battery capacity larger than my daily use?', a: 'Because you size for multiple days of autonomy and cannot use 100% of the battery. Days of autonomy multiply the load, and depth of discharge divides the usable fraction, so installed capacity is typically several times daily consumption.' },
    { q: 'Can I add batteries to an existing solar bank later?', a: 'With lithium you can often parallel additional matched modules, but mixing new and old or different chemistries is risky because the bank behaves like its weakest battery. It is usually best to size the bank correctly from the start.' },
  ],
  related: [
    { href: '/battery-bank-size-calculator/', badge: 'Ah', title: 'Battery Bank Size Calculator', desc: 'Autonomy-based bank sizing' },
    { href: '/off-grid-solar-calculator/', badge: 'Off', title: 'Off-Grid Solar Calculator', desc: 'Match panels to your bank' },
    { href: '/battery-runtime-calculator/', badge: 'h', title: 'Battery Runtime Calculator', desc: 'How long a bank runs a load' },
    { href: '/solar-panel-wattage-calculator/', badge: 'W', title: 'Solar Panel Wattage Calculator', desc: 'Size the array to recharge' },
    { href: '/solar-charge-controller-size-calculator/', badge: 'A', title: 'Charge Controller Size', desc: 'Protect the battery bank' },
    { href: '/amp-hours-to-watt-hours/', badge: 'Wh', title: 'Amp Hours to Watt Hours', desc: 'Convert Ah into energy' },
  ],
};

